//! Secret key types.
//!
//! Every type is generated by `secret_type!`: a fixed-size byte array that
//! zeroizes on drop and has no `Clone`, `Copy`, `Debug`, `Display`,
//! `Serialize` or `PartialEq`. Equality is only available through
//! [`subtle::ConstantTimeEq`]. Raw bytes are reachable only inside the crate.

use crate::rng::SecureRng;

/// Defines a secret key type of `$len` bytes.
macro_rules! secret_type {
    ($(#[$meta:meta])* $name:ident, $len:expr) => {
        $(#[$meta])*
        #[derive(zeroize::Zeroize, zeroize::ZeroizeOnDrop)]
        pub struct $name([u8; $len]);

        impl $name {
            /// Length in bytes.
            pub const LEN: usize = $len;

            /// Takes ownership of the bytes. Used by derivations and parsers.
            #[allow(dead_code)] // first used by later tasks
            pub(crate) fn from_array(bytes: [u8; $len]) -> Self {
                Self(bytes)
            }

            /// Draws fresh bytes from `rng`.
            #[allow(dead_code)] // first used by later tasks
            pub(crate) fn random<R: SecureRng>(rng: &mut R) -> Self {
                let mut bytes = [0u8; $len];
                rng.fill(&mut bytes);
                let key = Self(bytes);
                zeroize::Zeroize::zeroize(&mut bytes);
                key
            }

            /// Read access to the raw bytes. Never public.
            #[allow(dead_code)] // first used by later tasks
            pub(crate) fn expose(&self) -> &[u8; $len] {
                &self.0
            }

            /// Builds a key from fixed bytes. Only for tests and vector
            /// runners; absent from release builds.
            #[cfg(feature = "test-support")]
            pub fn from_test_bytes(bytes: [u8; $len]) -> Self {
                Self(bytes)
            }
        }

        impl subtle::ConstantTimeEq for $name {
            fn ct_eq(&self, other: &Self) -> subtle::Choice {
                subtle::ConstantTimeEq::ct_eq(self.0.as_slice(), other.0.as_slice())
            }
        }
    };
}

secret_type!(
    /// Vault key (VK).
    VaultKey,
    32
);
secret_type!(
    /// Item key (IK).
    ItemKey,
    32
);
secret_type!(
    /// Key-encryption key (KEK) for one unlock method.
    Kek,
    32
);
secret_type!(
    /// Recovery key (RK).
    RecoveryKey,
    32
);
secret_type!(
    /// Secret key (SK), the second factor mixed into the OPAQUE input.
    SecretKey,
    16
);
secret_type!(
    /// OPAQUE export key.
    ExportKey,
    64
);
secret_type!(
    /// Output of the WebAuthn PRF extension.
    PrfOutput,
    32
);
secret_type!(
    /// Seed derived from a PRF output.
    PrfSeed,
    32
);
secret_type!(
    /// Key for the checkpoint MAC and item tags.
    KHead,
    32
);
secret_type!(
    /// Key for tombstones.
    KDel,
    32
);
secret_type!(
    /// Key for the manifest.
    KMeta,
    32
);
secret_type!(
    /// Seed for the authentication key pair.
    AuthSeed,
    32
);
secret_type!(
    /// Content key of an export file (EK).
    ExportContentKey,
    32
);

impl VaultKey {
    /// A fresh random vault key.
    pub fn generate<R: SecureRng>(rng: &mut R) -> Self {
        Self::random(rng)
    }
}

impl RecoveryKey {
    /// A fresh random recovery key.
    pub fn generate<R: SecureRng>(rng: &mut R) -> Self {
        Self::random(rng)
    }
}

impl SecretKey {
    /// A fresh random secret key.
    pub fn generate<R: SecureRng>(rng: &mut R) -> Self {
        Self::random(rng)
    }
}
